#include <gtest/gtest.h>
#include "bignum.h"

using bignum::bigint;

TEST(BigintEquality_True, T1) { bigint a("0"); bigint b("0"); EXPECT_TRUE(a == b); }
TEST(BigintEquality_True, T2) { bigint a("0"); bigint b("0"); b.set_negative(true); EXPECT_TRUE(a == b); }
TEST(BigintEquality_True, T3) { bigint a("18446744073709551615"); bigint b("18446744073709551615"); EXPECT_TRUE(a == b); }
TEST(BigintEquality_True, T4) { bigint a("-18446744073709551615"); bigint b("-18446744073709551615"); EXPECT_TRUE(a == b); }
TEST(BigintEquality_True, T5) { bigint a("42"); bigint b("42"); EXPECT_TRUE(a == b); }
TEST(BigintEquality_True, T6) { bigint a("123456789012345678901234567890"); bigint b("123456789012345678901234567890"); EXPECT_TRUE(a == b); }
TEST(BigintEquality_True, T7) { bigint a("9999999999999999999999999999999999999999"); bigint b("9999999999999999999999999999999999999999"); EXPECT_TRUE(a == b); }
TEST(BigintEquality_True, T8) { bigint a("10000000000000000000000000000000000000000"); bigint b("10000000000000000000000000000000000000000"); EXPECT_TRUE(a == b); }
TEST(BigintEquality_True, T9) { bigint a("-9876543210987654321098765432109876543210"); bigint b("-9876543210987654321098765432109876543210"); EXPECT_TRUE(a == b); }
